std::vector<int> data = {1, 2, 3};

// MANUAL ITERATOR LOOP: Explicit Control
// Overhead: Initialization (begin), Condition (end), Increment (++it)
for (auto it = data.begin();
     it != data.end();
     ++it) // Use Prefix (++it) for iterator performance
{
    // Access: *it
    int& value = *it;

    // Note: Compiler often optimizes this form
    // into the equivalent of a pointer loop for vector/array.
}
